// GET /pages/<file> — one workbench file, served to the hub's preview frames.
//
// The pages live in workbench/ at the repo root and are generated by Python. They
// are read here rather than copied, so the hub always shows the current file.
// The path is resolved and must stay inside workbench/.

import { readFile } from "node:fs/promises";
import path from "node:path";
import { repoRoot } from "../../lib/gallery.js";

const TYPES = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".woff2": "font/woff2",
};

export const GET = async ({ params }) => {
  const relative = String(params.file || "");
  const dir = path.join(repoRoot(), "workbench");
  const file = path.resolve(dir, relative);
  if (!relative || file !== dir && !file.startsWith(dir + path.sep)) {
    return new Response("bad page path\n", { status: 400 });
  }
  try {
    const bytes = await readFile(file);
    return new Response(bytes, {
      status: 200,
      headers: {
        "content-type": TYPES[path.extname(file).toLowerCase()] || "application/octet-stream",
        "cache-control": "no-store",
      },
    });
  } catch {
    return new Response("no such workbench file\n", { status: 404 });
  }
};
